// Some portions generated by Co-Pilot
"use client";

import { Link } from "@/i18n/navigation";
import { useTranslations } from "next-intl";
import type { BinaryAssetView, TemurinAssets } from "@/types/temurin";
import { FaRegFileCode } from "react-icons/fa";
import { GrNotes, GrInstall } from "react-icons/gr";
import { GiFlatPlatform } from "react-icons/gi";

interface ReleaseLinksProps {
  selectedVersion: string;
  releases: BinaryAssetView[] | TemurinAssets;
}

const ReleaseLinks = ({ selectedVersion, releases }: ReleaseLinksProps) => {
  const t = useTranslations("Temurin.Releases.ReleaseLinks");
  if (!releases.length) return null;
  const source = "source" in releases ? releases.source : undefined;
  const version = Number(selectedVersion);
  const sourceUrl =
    source?.binary?.package?.link ||
    (Number.isInteger(version) && version > 0
      ? `https://github.com/adoptium/temurin${version}-binaries`
      : null);
  const links = [
    {
      key: "release-notes",
      href: source?.release_name
        ? `/temurin/release-notes/?version=${source.release_name}`
        : "/temurin/release-notes",
      icon: GrNotes,
    },
    { key: "installation-guide", href: "/installation", icon: GrInstall },
    {
      key: "supported-platforms",
      href: "/supported-platforms",
      icon: GiFlatPlatform,
    },
    ...(sourceUrl
      ? [
          {
            key: "source-code",
            href: sourceUrl,
            icon: FaRegFileCode,
          },
        ]
      : []),
  ];
  return (
    <nav className="mt-5" data-testid="release-links-section">
      <ul
        className="m-0 flex list-none flex-wrap items-center gap-x-6 gap-y-1 p-0"
        data-testid="release-links-list"
      >
        {links.map(({ key, href, icon: Icon }) => (
          <li key={key}>
            <Link
              href={href}
              target={key === "source-code" ? "_blank" : undefined}
              rel={key === "source-code" ? "noopener noreferrer" : undefined}
              className="inline-flex min-h-11 items-center gap-2 text-xs text-grey transition-colors hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink"
              data-testid={`${key}-link`}
            >
              <Icon aria-hidden="true" />
              <span>{t(key)}</span>
            </Link>
          </li>
        ))}
      </ul>
    </nav>
  );
};

export default ReleaseLinks;
